import os
from flask import Flask, request, abort, send_file

app = Flask(__name__)
REPORTS = os.path.abspath("./data/reports")

@app.route("/download")
def download():
    filename = request.args.get("filename", "")
    # Validate that the filename does not contain path traversal sequences
    if '..' in filename or filename.startswith('.'):
        abort(400)

    path = os.path.join(REPORTS, filename)
    # Ensure the path is within the expected directory and doesn't go outside
    if not path.startswith(REPORTS):
        abort(400)

    if not os.path.isfile(path):
        abort(404)

    return send_file(path)
