def read_note(name):
    # Construct the path with proper joining and validate it doesn't escape outside the notes directory
    path = os.path.join("./notes", name)

    # Validate that the path is within the expected directory (prevent directory traversal attacks)
    if not path.startswith("./notes"):
        raise ValueError("Invalid path: directory traversal attempt detected")

    # Read the file safely
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return fh.read()
    except FileNotFoundError:
        raise FileNotFoundError(f"Note file '{name}' not found")
    except PermissionError:
        raise PermissionError(f"Permission denied accessing note '{name}'")
    except Exception as e:
        raise Exception(f"Error reading note '{name}': {str(e)}")
