def load_template(template_name):
    path = TEMPLATES / template_name
    # Validate that the path is within the expected directory and not a directory itself
    if not path.is_file():
        raise FileNotFoundError(f"Template '{template_name}' not found")
    if not path.resolve().relative_to(TEMPLATES):
        raise PermissionError(f"Attempted to access template outside of allowed directory: '{template_name}'")
