        return NULL;
    }

    // Copy first name to buffer
    size_t first_len = strlen(first);
    if (first_len >= 128) {
        return NULL;
    }

    strcpy(buf, first);

    // Add space
    strcat(buf, " ");

    // Copy last name to buffer
    size_t last_len = strlen(last);
    size_t total_len = first_len + 1 + last_len;
    if (total_len >= 128) {
        return NULL;
    }

    strcat(buf, last);

    // Allocate memory for the full name
    full = malloc(total_len + 1);
    if (full == NULL) {
        return NULL;
    }

    strcpy(full, buf);

    return full;
}
